package main

import (
	"fmt"
	"strconv"
	"strings"
)

type statusContext struct {
	current entry
	files   []entry
}

type statusProgram struct {
	root statusExpr
}

type statusExpr interface {
	eval(statusContext) (any, error)
}

type literalExpr struct{ value any }

func (e literalExpr) eval(_ statusContext) (any, error) { return e.value, nil }

type identExpr struct{ name string }

func (e identExpr) eval(ctx statusContext) (any, error) {
	switch e.name {
	case "current_file":
		return ctx.current, nil
	case "files":
		out := make([]any, 0, len(ctx.files))
		for _, file := range ctx.files {
			out = append(out, file)
		}
		return out, nil
	default:
		return nil, fmt.Errorf("unknown identifier %q", e.name)
	}
}

type arrayExpr struct{ items []statusExpr }

func (e arrayExpr) eval(ctx statusContext) (any, error) {
	out := make([]any, 0, len(e.items))
	for _, item := range e.items {
		value, err := item.eval(ctx)
		if err != nil {
			return nil, err
		}
		out = append(out, value)
	}
	return out, nil
}

type callExpr struct {
	receiver statusExpr
	name     string
	args     []statusExpr
}

func (e callExpr) eval(ctx statusContext) (any, error) {
	var recv any
	var err error
	if e.receiver != nil {
		recv, err = e.receiver.eval(ctx)
		if err != nil {
			return nil, err
		}
	}
	args := make([]any, 0, len(e.args))
	for _, arg := range e.args {
		value, err := arg.eval(ctx)
		if err != nil {
			return nil, err
		}
		args = append(args, value)
	}
	return callStatusFunc(e.name, recv, args, ctx)
}

type pipeExpr struct {
	left statusExpr
	call callExpr
}

func (e pipeExpr) eval(ctx statusContext) (any, error) {
	value, err := e.left.eval(ctx)
	if err != nil {
		return nil, err
	}
	args := make([]statusExpr, 0, len(e.call.args)+1)
	args = append(args, literalExpr{value: value})
	args = append(args, e.call.args...)
	return callExpr{name: e.call.name, receiver: e.call.receiver, args: args}.eval(ctx)
}

func parseStatusProgramFromEnv() (*statusProgram, error) {
	source := strings.TrimSpace(strings.TrimSpace(getenv("WALK_STATUS_BAR")))
	if source == "" {
		return nil, nil
	}
	parser := statusParser{src: source}
	root, err := parser.parse()
	if err != nil {
		return nil, err
	}
	return &statusProgram{root: root}, nil
}

func getenv(key string) string {
	return strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimRight(strings.TrimLeft(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(strings.TrimSpace(os.Getenv(key)), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")), "\n")))
}

type statusParser struct {
	src string
	pos int
}

func (p *statusParser) parse() (statusExpr, error) {
	expr, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	p.skipSpace()
	if p.pos != len(p.src) {
		return nil, fmt.Errorf("unexpected token %q", p.src[p.pos:])
	}
	return expr, nil
}

func (p *statusParser) parsePipe() (statusExpr, error) {
	left, err := p.parsePrimary()
	if err != nil {
		return nil, err
	}
	for {
		p.skipSpace()
		if !p.consume('|') {
			return left, nil
		}
		p.skipSpace()
		call, err := p.parseCall(nil)
		if err != nil {
			return nil, err
		}
		left = pipeExpr{left: left, call: call}
	}
}

func (p *statusParser) parsePrimary() (statusExpr, error) {
	p.skipSpace()
	if p.pos >= len(p.src) {
		return nil, fmt.Errorf("unexpected token EOF")
	}
	switch p.src[p.pos] {
	case '"':
		return p.parseString()
	case '[':
		return p.parseArray()
	case '(':
		p.pos++
		expr, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		if !p.consume(')') {
			return nil, fmt.Errorf("unexpected token EOF")
		}
		return expr, nil
	default:
		if isDigit(p.src[p.pos]) {
			return p.parseNumber()
		}
		name, err := p.parseIdent()
		if err != nil {
			return nil, err
		}
		expr := statusExpr(identExpr{name: name})
		for {
			p.skipSpace()
			if p.consume('.') {
				method, err := p.parseIdent()
				if err != nil {
					return nil, err
				}
				call, err := p.parseCall(expr, method)
				if err != nil {
					return nil, err
				}
				expr = call
				continue
			}
			if p.peek() == '(' {
				call, err := p.parseCall(nil, name)
				if err != nil {
					return nil, err
				}
				expr = call
			}
			return expr, nil
		}
	}
}

func (p *statusParser) parseCall(receiver statusExpr, preset ...string) (callExpr, error) {
	name := ""
	if len(preset) != 0 {
		name = preset[0]
	} else {
		ident, err := p.parseIdent()
		if err != nil {
			return callExpr{}, err
		}
		name = ident
	}
	if !p.consume('(') {
		return callExpr{}, fmt.Errorf("unexpected token EOF")
	}

package main

import (
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"os/exec"
	"os/user"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"syscall"
	"time"
)

const (
	version = "v1.13.0"
	helpText = `
  walk v1.13.0

  Usage: walk [path]

    arrows, hjkl  Move cursor
    enter         Enter directory
    backspace     Exit directory
    space         Toggle preview
    esc, q        Exit with cd
    ctrl+c        Exit without cd
    /             Fuzzy search
    d, delete     Delete file or dir
    y             Copy to clipboard
    .             Hide hidden files
    ?             Show help

  Flags:

    --icons        display icons
    --dir-only     show dirs only
    --hide-hidden  hide hidden files
    --preview      display preview
    --with-border  preview with border
    --fuzzy        fuzzy mode
`
)

type options struct {
	showIcons   bool
	dirOnly     bool
	hideHidden  bool
	preview     bool
	withBorder  bool
	startFuzzy  bool
	startPath   string
	showHelp    bool
	showVersion bool
}

type app struct {
	tty  *tty
	opts options

	statusProg *statusProgram
	icons      *iconSet

	currentPath string
	errorState  string

	entries      []entry
	filtered     []int
	selected     int
	selectByName string

	preview     bool
	help        bool
	searchMode  bool
	searchShown bool
	query       string

	copyMessage string
	deleteArm   string
	pending     *pendingDelete

	pager *pager

	lastRenderLineCount int
	needRender          bool
}

type entry struct {
	Name       string
	Display    string
	FullPath   string
	LInfo      fs.FileInfo
	TargetInfo fs.FileInfo
}

type pendingDelete struct {
	Name       string
	Original   string
	StashDir   string
	ExpiresAt  time.Time
	LastRemain int
}

type pager struct {
	Path  string
	Lines []string
}

func main() {
	opts := parseArgs(os.Args[1:])
	if opts.showHelp {
		fmt.Fprint(os.Stdout, helpText)
		os.Exit(1)
	}
	if opts.showVersion {
		fmt.Fprintln(os.Stdout, version)
		return
	}

	t, err := openTTY()
	if err != nil {
		panic(fmt.Sprintf("could not open a new TTY: %v", err))
	}
	defer t.close()

	statusProg, err := parseStatusProgramFromEnv()
	if err != nil {
		panic(err)
	}

	var icons *iconSet
	if opts.showIcons {
		icons, _ = loadIconSet(filepath.Join("etc", "icons"))
	}

	startPath := opts.startPath
	if startPath == "" {
		startPath, err = os.Getwd()
		if err != nil {
			panic(err)
		}
	} else {
		startPath, err = filepath.Abs(startPath)
		if err != nil {
			panic(err)
		}
	}
	startPath = filepath.Clean(startPath)

	a := &app{
		tty:        t,
		opts:       opts,
		statusProg: statusProg,
		icons:      icons,
		currentPath: startPath,
		preview:     opts.preview,
		searchMode:  opts.startFuzzy,
	}
	if opts.startFuzzy {
		a.searchShown = false
	}

	if err := a.loadPath(startPath, ""); err != nil {
		panic(err)
	}
	if err := a.run(); err != nil && !errors.Is(err, errExitNoCD) {
		panic(err)
	}
}

var errExitNoCD = errors.New("exit without cd")

func parseArgs(args []string) options {
	var opts options
	for _, arg := range args {
		switch arg {
		case "-h", "--help":
			opts.showHelp = true
		case "--version":
			opts.showVersion = true
		case "--icons":
			opts.showIcons = true
		case "--dir-only":
			opts.dirOnly = true
		case "--hide-hidden":
			opts.hideHidden = true
		case "--preview":
			opts.preview = true
		case "--with-border":
			opts.withBorder = true
		case "--fuzzy":
			opts.startFuzzy = true
		default:
			if opts.startPath == "" {
				opts.startPath = arg
			}
		}
	}
	return opts
}

func (a *app) run() error {
	if err := a.tty.enterRaw(); err != nil {
		return err
	}
	defer a.tty.exitRaw()

	a.needRender = true
	for {
		a.tickPendingDelete()
		if a.needRender {
			if err := a.render(); err != nil {
				return err
			}
			a.needRender = false
		}

		ev, ok, err := a.tty.readEvent()
		if err != nil {
			return err
		}
		if !ok {
			continue
		}

		if a.pager != nil {
			switch ev.kind {
			case keyCtrlC, keyEsc, keyRune:
				if ev.kind == keyRune && ev.r != 'q' {
					continue
				}
				a.pager = nil
				a.needRender = true
			}
			continue
		}

		if a.help {
			switch ev.kind {
			case keyCtrlC:
				return errExitNoCD
			case keyEsc:
				return a.exitWithPath()
			case keyRune:
				if ev.r == 'q' {
					return a.exitWithPath()
				}
				a.help = false
				a.handleRune(ev.r)
				a.needRender = true
				continue
			default:
				a.help = false
				a.needRender = true
			}
		}

		}

		switch ev.kind {
		case keyCtrlC:
			return errExitNoCD
		case keyEsc:
			return a.exitWithPath()
		case keyEnter:
			if err := a.activate(); err != nil {
				return err
			}
		case keyBackspace:
			a.handleBackspace()
		case keyUp:
			a.moveSelection(-1)
		case keyDown:
			a.moveSelection(1)
		case keyJumpFirst:
			a.jumpSelection(0)
		case keyJumpLast:
			a.jumpSelection(len(a.filtered) - 1)
		case keyDelete:
			a.handleDelete()
		case keyRune:
			a.handleRune(ev.r)
		}
		a.needRender = true
	}
}

func (a *app) handleRune(r rune) {
	switch {
	case a.searchMode && r != '/' && r != '?' && r != ' ':
		if r >= 32 {
			a.query += string(r)
			a.searchShown = true
			a.deleteArm = ""
			a.applyFilter(true)
		}
		return
	case r == 'q':
		_ = a.exitWithPath()
	case r == 'j':
		a.moveSelection(1)
	case r == 'k':
		a.moveSelection(-1)
	case r == '.':
		a.opts.hideHidden = !a.opts.hideHidden
		a.reload("")
	case r == ' ':
		a.preview = !a.preview
	case r == '/':
		a.searchMode = true
		a.searchShown = true
		a.deleteArm = ""
		a.applyFilter(false)
	case r == '?':
		a.help = true
	case r == 'y':
		a.copySelected()
	case r == 'd':
		a.handleDelete()
	case r == 'u':
		a.undoDelete()
	}
}

func (a *app) handleBackspace() {
	if a.searchShown {
		if a.query != "" {
			a.query = trimLastRune(a.query)
			a.applyFilter(true)
			return
		}
		a.searchShown = false
		if !a.opts.startFuzzy {
			a.searchMode = false
		}
		a.applyFilter(false)
		return
	}
	parent := filepath.Dir(a.currentPath)
	if parent == "" {
		parent = string(os.PathSeparator)
	}
	if parent == a.currentPath {
		a.reload("")
		return
	}
	name := filepath.Base(a.currentPath)
	a.currentPath = parent
	a.errorState = ""
	_ = a.loadPath(parent, name)
}

func (a *app) moveSelection(delta int) {
	if len(a.filtered) == 0 {
		return
	}
	a.deleteArm = ""
	if a.selected < 0 {
		a.selected = 0
		return
	}
	a.selected = (a.selected + delta) % len(a.filtered)
	if a.selected < 0 {
		a.selected += len(a.filtered)
	}
}

func (a *app) jumpSelection(idx int) {
	if len(a.filtered) == 0 {
		return
	}
	a.deleteArm = ""
	if idx < 0 {
		idx = 0
	}
	if idx >= len(a.filtered) {
		idx = len(a.filtered) - 1
	}
	a.selected = idx
}

func (a *app) selectedEntry() *entry {
	if len(a.filtered) == 0 || a.selected < 0 || a.selected >= len(a.filtered) {
		return nil
	}
	return &a.entries[a.filtered[a.selected]]
}

func (a *app) activate() error {
	e := a.selectedEntry()
	if e == nil {
		return nil
	}
	if e.TargetInfo != nil && e.TargetInfo.IsDir() {
		a.currentPath = filepath.Join(a.currentPath, e.Name)
		a.errorState = ""
		return a.loadPath(a.currentPath, "")
	}
	return a.openFile(e.FullPath)
}

func (a *app) exitWithPath() error {
	if err := a.clearAndRestore(); err != nil {
		return err
	}
	_, err := fmt.Fprintln(os.Stdout, a.currentPath)
	return err
}

func (a *app) loadPath(path, selectName string) error {
	a.currentPath = filepath.Clean(path)
	a.errorState = ""
	a.copyMessage = ""
	a.deleteArm = ""

	items, err := os.ReadDir(a.currentPath)
	if err != nil {
		a.entries = nil
		a.filtered = nil
		a.selected = -1
		a.errorState = err.Error()
		return nil
	}

	var entries []entry
	for _, item := range items {
		name := item.Name()
		if a.opts.hideHidden && strings.HasPrefix(name, ".") {
			continue
		}
		full := filepath.Join(a.currentPath, name)
		linfo, lerr := os.Lstat(full)
		if lerr != nil {
			continue
		}
		if a.opts.dirOnly && !linfo.IsDir() {
			continue
		}
		targetInfo, _ := os.Stat(full)
		display := name
		if linfo.IsDir() {
			display += "/"
		}
		if a.icons != nil {
			if icon := a.icons.iconFor(name, linfo, targetInfo); icon != "" {
				display = icon + " " + display
			}
		}
		entries = append(entries, entry{
			Name:       name,
			Display:    display,
			FullPath:   full,
			LInfo:      linfo,
			TargetInfo: targetInfo,
		})
	}
	sort.Slice(entries, func(i, j int) bool {
		return strings.Compare(entries[i].Name, entries[j].Name) < 0
	})
	a.entries = entries
	a.applyFilter(false)
	if selectName != "" {
		for idx, entryIndex := range a.filtered {
			if a.entries[entryIndex].Name == selectName {
				a.selected = idx
				break
			}
		}
	}
	return nil
}

func (a *app) reload(selectName string) {
	_ = a.loadPath(a.currentPath, selectName)
}

func (a *app) applyFilter(fromQuery bool) {
	prevName := ""
	if e := a.selectedEntry(); e != nil {
		prevName = e.Name
	}
	a.filtered = a.filtered[:0]
	query := strings.ToLower(a.query)
	searchActive := a.searchMode && (a.searchShown || query != "")
	for i, e := range a.entries {
		if searchActive && query != "" && !fuzzyMatch(e.Name, query) {
			continue
		}
		a.filtered = append(a.filtered, i)
	}
	if len(a.filtered) == 0 {
		a.selected = -1
		return
	}
	if fromQuery && query != "" {
		a.selected = len(a.filtered) - 1
		return
	}
	if prevName != "" {
		for idx, entryIndex := range a.filtered {
			if a.entries[entryIndex].Name == prevName {
				a.selected = idx
				return
			}
		}
	}
	if a.selected < 0 || a.selected >= len(a.filtered) {
		a.selected = 0
	}
}

func (a *app) handleDelete() {
	e := a.selectedEntry()
	if e == nil {
		return
	}
	if a.deleteArm != e.FullPath {
		a.deleteArm = e.FullPath
		return
	}
	a.deleteArm = ""
	_ = a.performDelete(e)
}

func (a *app) performDelete(e *entry) error {
	a.discardPending()

	pd := &pendingDelete{
		Name:       e.Name,
		Original:   e.FullPath,
		ExpiresAt:  time.Now().Add(5 * time.Second),
		LastRemain: 5,
	}

	stashDir, err := os.MkdirTemp("", "walk-undo-*")
	if err == nil {
		stashPath := filepath.Join(stashDir, filepath.Base(e.FullPath))
		if copyPath(e.FullPath, stashPath) == nil {
			pd.StashDir = stashDir
		} else {
			_ = os.RemoveAll(stashDir)
		}
	}

	if cmd := os.Getenv("WALK_REMOVE_CMD"); cmd != "" {
		if err := a.runCommand(cmd, e.FullPath); err != nil {
			if pd.StashDir != "" {
				_ = os.RemoveAll(pd.StashDir)
			}
			return nil
		}
	} else {
		_ = os.RemoveAll(e.FullPath)
	}

	a.reloadAfterDelete(e.Name)
	a.pending = pd
	a.copyMessage = fmt.Sprintf("%s deleted. (u)ndo 5", e.Name)
	return nil
}

func (a *app) reloadAfterDelete(deletedName string) {
	_ = a.loadPath(a.currentPath, "")
	if len(a.filtered) == 0 {
		return
	}
	for idx, entryIndex := range a.filtered {
		if strings.Compare(a.entries[entryIndex].Name, deletedName) > 0 {
			a.selected = idx
			return
		}
	}
	a.selected = len(a.filtered) - 1
}

func (a *app) undoDelete() {
	if a.pending == nil {
		return
	}
	pd := a.pending
	a.pending = nil
	if pd.StashDir != "" {
		stashPath := filepath.Join(pd.StashDir, filepath.Base(pd.Original))
		if _, err := os.Lstat(pd.Original); err != nil {
			_ = copyPath(stashPath, pd.Original)
		}
		_ = os.RemoveAll(pd.StashDir)
	}
	a.copyMessage = ""
	a.reload(pd.Name)
}

func (a *app) discardPending() {
	if a.pending == nil {
		return
	}
	if a.pending.StashDir != "" {
		_ = os.RemoveAll(a.pending.StashDir)
	}
	a.pending = nil
}

func (a *app) tickPendingDelete() {
	if a.pending == nil {
		return
	}
	remaining := int(a.pending.ExpiresAt.Sub(time.Now()).Seconds())
	if remaining < 0 {
		remaining = 0
	}
	if remaining != a.pending.LastRemain {
		a.pending.LastRemain = remaining
		if remaining == 0 {
			a.copyMessage = ""
		} else {
			a.copyMessage = fmt.Sprintf("%s deleted. (u)ndo %d", a.pending.Name, remaining)
		}
		a.needRender = true

		a.needRender = true
	}
	if time.Now().After(a.pending.ExpiresAt) {
		a.discardPending()
		a.copyMessage = ""
		a.needRender = true
	}
}

func (a *app) copySelected() {
	target := a.currentPath
	if e := a.selectedEntry(); e != nil {
		target = e.FullPath
	}
	a.tty.copyOSC52(target)
	a.copyMessage = "copied: " + target
}

func (a *app) openFile(path string) error {
	if cmd := a.openCommandFor(path); cmd != "" {
		return a.runCommand(cmd, path)
	}
	lines, err := previewFileLines(path, 4096)
	if err != nil {
		lines = []string{}
	}
	a.pager = &pager{Path: path, Lines: lines}
	return nil
}

func (a *app) runCommand(cmdline, path string) error {
	if err := a.tty.suspend(); err != nil {
		return err
	}
	defer func() {
		_ = a.tty.resume()
		a.needRender = true
	}()

	cmd := exec.Command("sh", "-c", cmdline+" \"$1\"", "walk", path)
	cmd.Stdin = a.tty.file
	cmd.Stdout = a.tty.file
	cmd.Stderr = a.tty.file
	return cmd.Run()
}

func (a *app) openCommandFor(path string) string {
	ext := strings.TrimPrefix(strings.ToLower(filepath.Ext(path)), ".")
	if ext != "" {
		for _, pair := range parseOpenWith(os.Getenv("WALK_OPEN_WITH")) {
			if strings.EqualFold(pair.ext, ext) {
				return pair.cmd
			}
		}
	}
	if cmd := os.Getenv("WALK_EDITOR"); cmd != "" {
		return cmd
	}
	return os.Getenv("EDITOR")
}

func parseOpenWith(value string) []struct{ ext, cmd string } {
	var out []struct{ ext, cmd string }
	for _, part := range splitConfigList(value) {
		key, val, ok := strings.Cut(part, ":")
		if !ok {
			continue
		}
		key = strings.TrimSpace(strings.TrimPrefix(key, "."))
		val = strings.TrimSpace(val)
		if key == "" || val == "" {
			continue
		}
		out = append(out, struct{ ext, cmd string }{ext: key, cmd: val})
	}
	return out
}

func splitConfigList(value string) []string {
	value = strings.ReplaceAll(value, "\n", ",")
	value = strings.ReplaceAll(value, ";", ",")
	parts := strings.Split(value, ",")
	out := make([]string, 0, len(parts))
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if part != "" {
			out = append(out, part)
		}
	}
	return out
}

func (a *app) clearAndRestore() error {
	lines := a.renderedLinesEstimate()
	if lines > 0 {
		fmt.Fprintf(a.tty.file, "\x1b[%dA", lines)
		for i := 0; i < lines; i++ {
			fmt.Fprint(a.tty.file, "\r\x1b[K\n")
		}
		fmt.Fprint(a.tty.file, "\x1b[K\r")
	}
	return nil
}

func (a *app) renderedLinesEstimate() int {
	if a.lastRenderLineCount > 0 {
		return a.lastRenderLineCount
	}
	return 1
}

func (a *app) render() error {
	width, height := a.tty.size()
	if width <= 0 {
		width = 80
	}
	if height <= 0 {
		height = 24
	}

	lines := a.buildLines(width, height)
	a.lastRenderLineCount = len(lines)

	fmt.Fprint(a.tty.file, "\r")
	for i, line := range lines {
		fmt.Fprint(a.tty.file, line)
		fmt.Fprint(a.tty.file, "\x1b[K")
		if i != len(lines)-1 {
			fmt.Fprint(a.tty.file, "\r\n")
		}
	}
	fmt.Fprintf(a.tty.file, "\x1b[%dD", width)
	return nil
}

func (a *app) buildLines(width, height int) []string {
	if a.pager != nil {
		return buildPagerLines(a.pager, width, height)
	}
	if a.help {
		return buildHelpLines(width, height)
	}

	lines := make([]string, 0, height)
	if a.preview {
		leftW, sep, rightW := previewLayout(width, a.opts.withBorder)
		leftTitle := basename(a.currentPath)
		if a.errorState != "" {
			leftTitle = basename(a.currentPath)
		}
		rightTitle := ""
		if e := a.selectedEntry(); e != nil {
			rightTitle = e.Name
		}
		lines = append(lines, padOrTrim(leftTitle, leftW)+sep+padOrTrim(rightTitle, rightW))

		previewLines := a.previewLines(rightW, height-1)
		bodyCount := max(len(a.filtered), len(previewLines))
		if bodyCount == 0 {
			bodyCount = len(boxLines("No files", rightW))
		}
		for row := 0; row < bodyCount && len(lines) < height; row++ {
			left := ""
			if row < len(a.filtered) {
				left = a.entries[a.filtered[row]].Display
			}
			right := ""
			if row < len(previewLines) {
				right = previewLines[row]
			}
			lines = append(lines, padOrTrim(left, leftW)+sep+padOrTrim(right, rightW))
		}
	} else {
		lines = append(lines, padOrTrim(a.pathBar(), width))
		if a.errorState != "" {
			box := boxLines(a.errorState, width)
			lines = append(lines, box...)
		} else if len(a.filtered) == 0 {
			lines = append(lines, boxLines("No files", width)...)
		} else {
			for _, idx := range a.filtered {
				lines = append(lines, padOrTrim(a.entries[idx].Display, width))
			}
		}
	}

	if a.statusProg != nil {
		if line, ok := a.statusLine(width); ok && len(lines) < height {
			lines = append(lines, padOrTrim(line, width))
		}
	}
	if a.copyMessage != "" && len(lines) < height {
		lines = append(lines, padOrTrim(a.copyMessage, width))
	}
	return trimToHeight(lines, height)
}

func (a *app) pathBar() string {
	if a.searchShown {
		return a.currentPath + "/" + a.query
	}
	return a.currentPath
}

func (a *app) previewLines(width, height int) []string {
	e := a.selectedEntry()
	if e == nil {
		return nil
	}
	if e.TargetInfo != nil && e.TargetInfo.IsDir() {
		items, err := os.ReadDir(e.FullPath)
		if err != nil {
			return boxLines(err.Error(), width)
		}
		if len(items) == 0 {
			return boxLines("No files", width)
		}
		lines := make([]string, 0, len(items))
		for _, item := range items {
			name := item.Name()
			if info, err := os.Lstat(filepath.Join(e.FullPath, name)); err == nil && info.IsDir() {
				name += "/"
			}
			lines = append(lines, name)
		}
		sort.Slice(lines, func(i, j int) bool { return strings.Compare(lines[i], lines[j]) < 0 })
		return trimToHeight(lines, height)
	}
	lines, _ := previewFileLines(e.FullPath, 65536)
	return trimToHeight(lines, height)
}

func (a *app) statusLine(width int) (string, bool) {
	e := a.selectedEntry()
	if e == nil || a.statusProg == nil {
		return "", false
	}
	value, err := a.statusProg.eval(statusContext{
		current: *e,
		files:   a.entries,
	})
	if err != nil {
		return "", false
	}
	return fmt.Sprint(value), true
}

func buildHelpLines(width, height int) []string {
	lines := []string{
		"help",
		"",
		"    arrows, hjkl  Move cursor",
		"    enter         Enter directory",
		"    backspace     Exit directory",
		"    space         Toggle preview",
		"    esc, q        Exit with cd",
		"    ctrl+c        Exit without cd",
		"    /             Fuzzy search",
		"    d, delete     Delete file or dir",
		"    y             Copy to clipboard",
		"    .             Hide hidden files",
		"    ?             Show help",
	}
	for i := range lines {
		lines[i] = padOrTrim(lines[i], width)
	}
	return trimToHeight(lines, height)
}

func buildPagerLines(p *pager, width, height int) []string {
	lines := make([]string, 0, height)
	contentHeight := max(0, height-1)
	for i := 0; i < contentHeight && i < len(p.Lines); i++ {
		lines = append(lines, padOrTrim(p.Lines[i], width))
	}
	for len(lines) < contentHeight {
		lines = append(lines, "")
	}
	status := p.Path + " (END)"
	lines = append(lines, padOrTrim(status, width))
	return lines
}

func previewLayout(width int, border bool) (int, string, int) {
	if width < 20 {
		return width, "", 0
	}
	if border {
		left := width/2 - 3
		if left < 1 {
			left = width / 2
		}
		right := width - left - 3
		return left, " │ ", right
	}
	left := width/2 - 2
	if left < 1 {
		left = width / 2
	}
	right := width - left - 2
	return left, "  ", right
}

func previewFileLines(path string, limit int64) ([]string, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	if limit > 0 {
		if _, err := io.CopyN(io.Discard, f, 0); err != nil {
			return nil, err
		}
	}
	data, err := io.ReadAll(io.LimitReader(f, limit))
	if err != nil {
		return nil, err
	}
	text := strings.ReplaceAll(string(data), "\r\n", "\n")
	text = strings.ReplaceAll(text, "\r", "\n")
	return strings.Split(text, "\n"), nil
}

func basename(path string) string {
	if path == string(os.PathSeparator) {
		return path
	}
	return filepath.Base(path)
}

func boxLines(message string, width int) []string {
	if width <= 0 {
		width = len(message) + 4
	}
	inner := len(message) + 2
	if inner < 10 {
		inner = 10
	}
	if inner+2 > width {
		inner = max(1, width-2)
		message = trimString(message, inner-2)
	}
	top := "╭" + strings.Repeat("─", inner) + "╮"
	body := "│ " + padOrTrim(message, inner-2) + " │"
	bottom := "╰" + strings.Repeat("─", inner) + "╯"
	return []string{top, body, bottom}
}

func padOrTrim(s string, width int) string {
	if width <= 0 {
		return ""
	}
	return padRight(trimString(s, width), width)
}

func trimString(s string, width int) string {
	runes := []rune(s)
	if len(runes) <= width {
		return s
	}

