}

func (p *statusParser) parseString() (statusExpr, error) {
	p.pos++
	start := p.pos
	for p.pos < len(p.src) && p.src[p.pos] != '"' {
		if p.src[p.pos] == '\\' && p.pos+1 < len(p.src) {
			p.pos += 2
			continue
		}
		p.pos++
	}
	if p.pos >= len(p.src) {
		return nil, fmt.Errorf("unexpected token EOF")
	}
	raw := p.src[start:p.pos]
	p.pos++
	raw = strings.ReplaceAll(raw, `\"`, `"`)
	return literalExpr{value: raw}, nil
}

func (p *statusParser) parseNumber() (statusExpr, error) {
	start := p.pos
	for p.pos < len(p.src) && isDigit(p.src[p.pos]) {
		p.pos++
	}
	n, err := strconv.Atoi(p.src[start:p.pos])
	if err != nil {
		return nil, err
	}
	return literalExpr{value: n}, nil
}

func (p *statusParser) parseArray() (statusExpr, error) {
	p.pos++
	var items []statusExpr
	for {
		p.skipSpace()
		if p.consume(']') {
			return arrayExpr{items: items}, nil
		}
		item, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		items = append(items, item)
		p.skipSpace()
		if p.consume(']') {
			return arrayExpr{items: items}, nil
		}
		if !p.consume(',') {
			return nil, fmt.Errorf("unexpected token EOF")
		}
	}
}

func (p *statusParser) parseIdent() (string, error) {
	p.skipSpace()
	start := p.pos
	for p.pos < len(p.src) {
		r := p.src[p.pos]
		if r == '_' || r == '-' || isAlpha(r) || isDigit(r) {
			p.pos++
			continue
		}
		break
	}
	if start == p.pos {
		return "", fmt.Errorf("unexpected token EOF")
	}
	return p.src[start:p.pos], nil
}

func (p *statusParser) skipSpace() {
	for p.pos < len(p.src) && (p.src[p.pos] == ' ' || p.src[p.pos] == '\t' || p.src[p.pos] == '\n') {
		p.pos++
	}
}

func (p *statusParser) consume(ch byte) bool {
	p.skipSpace()
	if p.pos < len(p.src) && p.src[p.pos] == ch {
		p.pos++
		return true
	}
	return false
}

func (p *statusParser) peek() byte {
	p.skipSpace()
	if p.pos >= len(p.src) {
		return 0
	}
	return p.src[p.pos]
}

func isDigit(b byte) bool { return b >= '0' && b <= '9' }
func isAlpha(b byte) bool { return (b >= 'a' && b <= 'z') || (b >= 'A' && b <= 'Z') }

func callStatusFunc(name string, receiver any, args []any, ctx statusContext) (any, error) {
	switch name {
	case "Sprintf":
		if len(args) == 0 {
			return "", nil
		}
		format := fmt.Sprint(args[0])
		return fmt.Sprintf(format, args[1:]...), nil
	case "PadLeft":
		if len(args) < 2 {
			return "", nil
		}
		return padLeft(fmt.Sprint(args[0]), asInt(args[1])), nil
	case "PadRight":
		if len(args) < 2 {
			return "", nil
		}
		return padRight(fmt.Sprint(args[0]), asInt(args[1])), nil
	case "Size":
		info := entryInfo(receiver, ctx.current)
		return formatSize(info), nil
	case "Mode":
		info := entryInfo(receiver, ctx.current)
		return formatMode(info), nil
	case "ModTime":
		info := entryInfo(receiver, ctx.current)
		return formatModTime(info), nil
	case "Owner":
		info := entryInfo(receiver, ctx.current)
		return formatOwner(info), nil
	case "join":
		if len(args) < 2 {
			return "", nil
		}
		items, _ := args[0].([]any)
		parts := make([]string, 0, len(items))
		for _, item := range items {
			parts = append(parts, fmt.Sprint(item))
		}
		return strings.Join(parts, fmt.Sprint(args[1])), nil
	case "Name":
		switch value := receiver.(type) {
		case entry:
			return value.Name, nil
		default:
			return "", nil
		}
	default:
		return nil, fmt.Errorf("unknown function %q", name)
	}
}

func entryInfo(receiver any, fallback entry) fs.FileInfo {
	switch value := receiver.(type) {
	case entry:
		return value.LInfo
	default:
		return fallback.LInfo
	}
}

func asInt(v any) int {
	switch value := v.(type) {
	case int:
		return value
	case int64:
		return int(value)
	case float64:
		return int(value)
	default:
		n, _ := strconv.Atoi(fmt.Sprint(v))
		return n
	}
}

