func evalStatusFunction(name string, piped any, args []any, ctx statusContext) (any, error) {
	callArgs := make([]any, 0, len(args)+1)
	if piped != nil {
		callArgs = append(callArgs, piped)
	}
	callArgs = append(callArgs, args...)
	switch name {
	case "Sprintf":
		if len(callArgs) == 0 {
			return "", nil
		}
		format := toString(callArgs[0])
		return fmt.Sprintf(format, callArgs[1:]...), nil
	case "PadLeft":
		if len(callArgs) < 2 {
			return "", nil
		}
		return padLeft(toString(callArgs[0]), toInt(callArgs[1])), nil
	case "PadRight":
		if len(callArgs) < 2 {
			return "", nil
		}
		return padRight(toString(callArgs[0]), toInt(callArgs[1])), nil
	case "join":
		if len(callArgs) < 2 {
			return "", nil
		}
		parts := toSlice(callArgs[0])
		sep := toString(callArgs[1])
		text := make([]string, 0, len(parts))
		for _, part := range parts {
			text = append(text, toString(part))
		}
		return strings.Join(text, sep), nil
	case "Size":
		if ctx.current == nil {
			return "", nil
		}
		return humanSize(ctx.current.size), nil
	case "Mode":
		if ctx.current == nil {
			return "", nil
		}
		return ctx.current.mode.String(), nil
	case "ModTime":
		if ctx.current == nil {
			return "", nil
		}
		return ctx.current.modTime.Format("Jan _2 15:04"), nil
	case "Owner":
		if ctx.current == nil {
			return "", nil
		}
		return formatOwner(ctx.current), nil
	default:
		return nil, fmt.Errorf("unknown function %q", name)
	}
}

func padLeft(s string, n int) string {
	if len(s) >= n {
		return s
	}
	return strings.Repeat(" ", n-len(s)) + s
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s
	}
	return s + strings.Repeat(" ", n-len(s))
}

func toInt(value any) int {
	switch v := value.(type) {
	case int:
		return v
	case int64:
		return int(v)
	case float64:
		return int(v)
	case string:
		n, _ := strconv.Atoi(v)
		return n
	default:
		return 0
	}
}

func toSlice(value any) []any {
	switch v := value.(type) {
	case []any:
		return v
	default:
		return nil
	}
}

func toString(value any) string {
	switch v := value.(type) {
	case nil:
		return ""
	case string:
		return v
	case int:
		return strconv.Itoa(v)
	case int64:
		return strconv.FormatInt(v, 10)
	case float64:
		return strconv.FormatFloat(v, 'f', -1, 64)
	case time.Time:
		return v.Format(time.RFC3339)
	case *entry:
		if v == nil {
			return ""
		}
		return v.name
	default:
		return fmt.Sprint(v)
	}
}

func humanSize(size int64) string {
	units := []string{"B", "KB", "MB", "GB", "TB"}
	value := float64(size)
	unit := 0
	for value >= 1024 && unit < len(units)-1 {
		value /= 1024
		unit++
	}
	if unit == 0 {
