func formatOwner(ent *entry) string {
	if ent == nil || ent.stat == nil {
		return ""
	}
	uid := strconv.FormatUint(uint64(ent.stat.Uid), 10)
	gid := strconv.FormatUint(uint64(ent.stat.Gid), 10)
	userName := uid
	groupName := gid
	if u, err := user.LookupId(uid); err == nil && u.Username != "" {
		userName = u.Username
	}
	if g, err := user.LookupGroupId(gid); err == nil && g.Name != "" {
		groupName = g.Name
	}
	return userName + " " + groupName
}

