		}
	}
	return token{kind: tokenEOF, pos: len(l.source)}

scan:
	start := l.pos
	switch ch := l.source[l.pos]; ch {
	case '(':
		l.pos++
		return token{kind: tokenLParen, text: "(", pos: start}
	case ')':
		l.pos++
		return token{kind: tokenRParen, text: ")", pos: start}
	case '[':
		l.pos++
		return token{kind: tokenLBracket, text: "[", pos: start}
	case ']':
		l.pos++
		return token{kind: tokenRBracket, text: "]", pos: start}
	case ',':
		l.pos++
		return token{kind: tokenComma, text: ",", pos: start}
	case '|':
		l.pos++
		return token{kind: tokenPipe, text: "|", pos: start}
	case '"':
		l.pos++
		var builder strings.Builder
		for l.pos < len(l.source) {
			c := l.source[l.pos]
			if c == '"' {
				l.pos++
				return token{kind: tokenString, text: builder.String(), pos: start}
			}
			if c == '\\' && l.pos+1 < len(l.source) {
				l.pos++
				builder.WriteByte(l.source[l.pos])
				l.pos++
				continue
			}
			builder.WriteByte(c)
			l.pos++
		}
		return token{kind: tokenEOF, pos: len(l.source)}
	default:
		if isIdentStart(ch) {
			l.pos++
			for l.pos < len(l.source) && isIdentPart(l.source[l.pos]) {
				l.pos++
			}
			return token{kind: tokenIdent, text: l.source[start:l.pos], pos: start}
		}
		if ch >= '0' && ch <= '9' {
			l.pos++
			for l.pos < len(l.source) && l.source[l.pos] >= '0' && l.source[l.pos] <= '9' {
