func parseStatusProgramFromEnv() (*statusProgram, error) {
	source := os.Getenv("WALK_STATUS_BAR")
	if source == "" {
		return nil, nil
	}
	return compile(source)
}

func compile(source string) (*statusProgram, error) {
	lex := newLexer(source)
	parser := &statusParser{
		source: source,
		lex:    lex,
		token:  lex.next(),
	}
	root, err := parser.parseExpr()
	if err != nil {
		panic(err)
	}
	if parser.token.kind != tokenEOF {
		panic(parser.unexpected(parser.token))
	}
	return &statusProgram{source: source, root: root}, nil
}

