func (n pipeNode) eval(ctx statusContext) (any, error) {
	left, err := n.left.eval(ctx)
	if err != nil {
		return nil, err
	}
	args := make([]any, 0, len(n.args))
	for _, arg := range n.args {
		value, err := arg.eval(ctx)
		if err != nil {
