		}
		args = append(args, value)
	}
	return evalStatusFunction(n.name, left, args, ctx)
}

func evalStatusFunction(name string, piped any, args []any, ctx statusContext) (any, error) {
	callArgs := make([]any, 0, len(args)+1)
	if piped != nil {
		callArgs = append(callArgs, piped)
	}
	callArgs = append(callArgs, args...)

	info := ctx.current.LInfo
	if ctx.current.TargetInfo != nil {
		info = ctx.current.TargetInfo
	}

	switch name {
	case "Sprintf":
		if len(callArgs) == 0 {
			return "", nil
		}
		format := toStatusString(callArgs[0])
		return fmt.Sprintf(format, callArgs[1:]...), nil
	case "PadLeft":
		if len(callArgs) < 2 {
			return "", nil
		}
		return padLeft(toStatusString(callArgs[0]), toStatusInt(callArgs[1])), nil
	case "PadRight":
		if len(callArgs) < 2 {
			return "", nil
		}
		return padRight(toStatusString(callArgs[0]), toStatusInt(callArgs[1])), nil
	case "join":
		if len(callArgs) < 2 {
			return "", nil
		}
		parts := toStatusSlice(callArgs[0])
		sep := toStatusString(callArgs[1])
		out := make([]string, 0, len(parts))
		for _, part := range parts {
			out = append(out, toStatusString(part))
		}
		return strings.Join(out, sep), nil
	case "Size":
		if info == nil {
			return "", nil
		}
		return formatSize(info), nil
	case "Mode":
		if info == nil {
			return "", nil
		}
		return formatMode(info), nil
	case "ModTime":
		if info == nil {
			return "", nil
		}
		return info.ModTime().Format("Jan _2 15:04"), nil
	case "Owner":
		if info == nil {
			return "", nil
		}
		return formatOwner(info), nil
	default:
		return nil, fmt.Errorf("unknown function %q", name)
	}
}

func toStatusString(value any) string {
	switch v := value.(type) {
	case nil:
		return ""
	case string:
		return v
	case int:
		return strconv.Itoa(v)
	case int64:
		return strconv.FormatInt(v, 10)
	case float64:
		return strconv.FormatFloat(v, 'f', -1, 64)
	case entry:
		return v.Name
	default:
		return fmt.Sprint(v)
	}
}

func toStatusInt(value any) int {
	switch v := value.(type) {
	case int:
		return v
	case int64:
		return int(v)
	case float64:
		return int(v)
	case string:
		n, _ := strconv.Atoi(v)
		return n
	default:
		return 0
	}
}

func toStatusSlice(value any) []any {
	switch v := value.(type) {
	case []any:
		return v
	default:
		return nil
	}
}

